input.command:
python3 -c "import os,json,urllib.request,urllib.error; token=os.environ.get('IVX_OWNER_TOKEN','').strip(); req=urllib.request.Request('https://api.ivxholding.com/api/ivx/developer-deploy/status',headers={'Accept':'application/json','Authorization':'Bearer '+token});
try:
 with urllib.request.urlopen(req,timeout=30) as r:
  b=json.load(r); print(json.dumps({'httpStatus':r.status,'ok':b.get('ok'),'data':b.get('data'),'keys':sorted(b.keys())},sort_keys=True))
except urllib.error.HTTPError as e:
 raw=e.read().decode('utf-8');
 try: b=json.loads(raw)
 except Exception: b={'error':'Non-JSON error response'}
 print(json.dumps({'httpStatus':e.code,'ok':b.get('ok'),'error':b.get('error'),'message':b.get('message')},sort_keys=True))"

